package ncasa.shoppinglist.application;
import java.time.Clock;import java.util.*;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class UpdateShoppingItemUseCase{private final ShoppingListRepository lists;private final ShoppingItemRepository items;private final ShoppingListHouseholdAccessPort access;private final Clock clock;public UpdateShoppingItemUseCase(ShoppingListRepository l,ShoppingItemRepository i,ShoppingListHouseholdAccessPort a,Clock c){lists=l;items=i;access=a;clock=c;}public ShoppingItem execute(Long actor,UUID household,UUID listId,UUID itemId,long version,ShoppingItemCommand command){var ctx=access.getContext(household,actor);ctx.requireActive(command.responsibleMemberId());var list=GetShoppingListUseCase.load(lists,listId,household);list.requireActive();var item=load(items,itemId,listId);check(item,version);item.edit(command.name(),command.quantity(),command.unit(),command.customUnit(),command.note(),command.responsibleMemberId(),clock.instant());var saved=items.save(item);lists.touchContent(listId,clock.instant());return saved;}static ShoppingItem load(ShoppingItemRepository i,UUID id,UUID l){return i.find(id,l).orElseThrow(ShoppingItemNotFoundException::new);}static void check(ShoppingItem i,long v){if(i.version()!=v)throw new ShoppingListConflictException("Shopping item changed concurrently");}}
